          longDescription:'This Grade 7 Social Studies course follows the KICD Junior School Grade 7 design (rationalised 2024), which integrates History, Geography, Citizenship and Life Skills Education around the theme “Living Together”. Its strands are Social Studies and Personal Development (self-exploration, entrepreneurial opportunities in Social Studies), People and Relationships (human origin, early civilisation, slavery and servitude, developments in medium of trade, diversity and interpersonal relationships, peaceful coexistence), Community Service-Learning, Natural and Historic Built Environments in Africa (historical information, historical development of agriculture, maps and map work, the Earth and the solar system, weather, fieldwork) and Political Development and Governance (political development in Africa, the Constitution of Kenya, human rights, African diasporas, citizenship). Each strand opens with an overview, its learning outcomes and an introduction, and every sub-strand has three lessons, a practical activity, a quiz, an assignment, a revision page and a summary. Batch 1 covers Self-Exploration and Entrepreneurial Opportunities in Social Studies.',
